cd /workspace && python3 -c "
import csv, io
csv.field_size_limit(50)
data='a,b\n1,2\n\"x\ny\",3\n'
r=csv.reader(io.StringIO(data, newline=''), strict=True)
for row in r: print(row)
try:
    r=csv.reader(io.StringIO('a,b\n1,'+'z'*60+'\n', newline=''), strict=True)
    for row in r: print(row)
except csv.Error as e: print('csv error:',e)
try:
    r=csv.reader(io.StringIO('a,b\n1,\"2\n', newline=''), strict=True)
    for row in r: print('row',row)
except csv.Error as e: print('strict error:',e)
"
